<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref,watch } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { api,errorText } from '../api'
import { useAuth } from '../stores/auth'
import { listItems,validateAssignment } from '../domain'
import type { Row } from '../domain'
const auth=useAuth(),router=useRouter(),form=ref<Row>({title:'',content:'',companyId:auth.me?.companyId,priority:'NORMAL',deadline:'',hostDeptId:'',collaboratorDeptIds:[]}),departments=ref<Row[]>([]),collaborationDepartments=ref<Row[]>([]),assignmentReason=ref(''),match=ref<Row|null>(null),matchError=ref(''),error=ref(''),matching=ref(false),busy=ref(false),draftState=ref(''),loaded=ref(false)
const draftKey=`task-draft:${auth.me?.id}:${auth.me?.companyId}:${auth.me?.role}`
const companies=computed(()=>[...new Set([auth.me?.companyId,...(auth.me?.scopes.map(s=>s.companyId)??[])])].filter(Boolean))
const suggestionChanged=computed(()=>{const suggestions=match.value?.suggestions??[];if(!suggestions.length)return false;const host=suggestions.find((s:Row)=>s.role==='HOST');const collaborators=suggestions.filter((s:Row)=>s.role==='COLLABORATOR').slice(0,2).map((s:Row)=>String(s.deptId)).sort();return String(host?.deptId)!==String(form.value.hostDeptId)||JSON.stringify(collaborators)!==JSON.stringify(form.value.collaboratorDeptIds.map(String).sort())})
let matchTimer:ReturnType<typeof setTimeout>,saveTimer:ReturnType<typeof setInterval>,sequence=0
async function fetchMatch(){if(form.value.title.length+form.value.content.length<3)return;const seq=++sequence;matching.value=true;matchError.value='';try{const result=await api.post('/tasks/match',{title:form.value.title,content:form.value.content,companyId:form.value.companyId});if(seq===sequence)match.value=result}catch(e){if(seq===sequence){matchError.value=errorText(e);match.value=null}}finally{if(seq===sequence)matching.value=false}}
watch(()=>[form.value.title,form.value.content,form.value.companyId],()=>{clearTimeout(matchTimer);sequence++;matching.value=false;match.value=null;if(loaded.value)matchTimer=setTimeout(fetchMatch,300)})
function applySuggestion(s:Row){if(s.role==='HOST'||s.role==='MASTER'){form.value.hostDeptId=s.deptId;form.value.collaboratorDeptIds=form.value.collaboratorDeptIds.filter((id:string)=>id!==s.deptId)}else if(form.value.collaboratorDeptIds.length<2&&s.deptId!==form.value.hostDeptId&&!form.value.collaboratorDeptIds.includes(s.deptId))form.value.collaboratorDeptIds.push(s.deptId);else ElMessage.warning('协办最多两个，且不能与主办部门重复')}
function saveDraft(){if(!form.value.title&&!form.value.content)return;try{sessionStorage.setItem(draftKey,JSON.stringify(form.value));draftState.value=`草稿已保存于本次浏览会话 ${new Date().toLocaleTimeString('zh-CN')}`}catch{draftState.value='浏览器无法保存草稿，请及时提交'}}
function clearDraft(){sessionStorage.removeItem(draftKey);draftState.value='本次草稿已清除'}
async function create(){if(busy.value)return;error.value=validateAssignment(form.value.hostDeptId,form.value.collaboratorDeptIds);if(error.value)return;if(!form.value.title.trim()||!form.value.content.trim()||!form.value.deadline){error.value='请完善任务标题、内容要求及截止时间';return}if(new Date(form.value.deadline).getTime()<=Date.now()){error.value='截止时间必须晚于当前时间';return}if(suggestionChanged.value&&!assignmentReason.value.trim()){error.value='请说明调整分配建议的原因';return}busy.value=true;try{const result=await api.post('/tasks',form.value);if(match.value?.matchingResultId){try{await api.post('/matching/feedback',{taskId:result.id,matchingResultId:match.value.matchingResultId,reason:assignmentReason.value.trim()||(match.value.suggestions?.length?'采用职能建议':'未命中规则，人工指定责任部门')})}catch(e){ElMessage.warning('任务已创建，匹配反馈未保存：'+errorText(e))}}clearDraft();ElMessage.success('任务已创建，请核对并确认分配');router.replace('/tasks/'+result.id)}catch(e){error.value=errorText(e)}finally{busy.value=false}}
onMounted(async()=>{try{departments.value=listItems(await api.get('/organization/departments'));try{collaborationDepartments.value=listItems(await api.get('/organization/collaboration-departments'))}catch{collaborationDepartments.value=departments.value;matchError.value='暂时无法加载跨公司协办目录，可继续选择本公司部门'}const saved=sessionStorage.getItem(draftKey);if(saved){const parsed=JSON.parse(saved);if(parsed.companyId===auth.me?.companyId){form.value={...form.value,...parsed};draftState.value='已恢复本次会话草稿'}}}catch(e){error.value=errorText(e)}loaded.value=true;saveTimer=setInterval(saveDraft,30000)})
onBeforeUnmount(()=>{clearTimeout(matchTimer);clearInterval(saveTimer);sequence++})
</script>
<template><section class="page-heading"><div><p class="eyebrow">CREATE A TASK</p><h1>布置任务</h1><p class="muted">明确目标与责任，职能匹配提供建议，由您确认最终分配。</p></div><el-button @click="$router.back()">返回任务列表</el-button></section><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><div class="create-layout"><section class="panel"><div class="panel-heading"><h2><span class="section-number">01</span>任务基本信息</h2><small>带 * 为必填</small></div><el-form label-position="top" @submit.prevent="create"><el-form-item label="任务标题" required><el-input v-model="form.title" maxlength="200" show-word-limit placeholder="清晰描述要完成的工作目标"/></el-form-item><el-form-item label="内容与交付要求" required><el-input v-model="form.content" type="textarea" :rows="7" maxlength="10000" show-word-limit placeholder="请描述背景、工作要求、成果形式与验收标准"/></el-form-item><div class="form-grid"><el-form-item label="任务所属公司" required><el-select v-model="form.companyId"><el-option v-for="c in companies" :key="c" :value="c" :label="c"/></el-select></el-form-item><el-form-item label="优先级" required><el-select v-model="form.priority"><el-option label="低" value="LOW"/><el-option label="中" value="NORMAL"/><el-option label="高" value="HIGH"/></el-select></el-form-item><el-form-item label="截止时间（北京时间）" required><el-date-picker v-model="form.deadline" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" style="width:100%"/></el-form-item></div><div class="section-rule"/><h2><span class="section-number">02</span>责任分配</h2><p class="muted">主办部门恰好一个，协办部门零至两个。跨公司协办需由对方确认。</p><el-form-item label="主办部门" required><el-select v-model="form.hostDeptId" filterable placeholder="选择唯一主办部门"><el-option v-for="d in departments" :key="d.id" :value="d.id" :label="`${d.companyName||d.companyId||''} / ${d.name}`"/></el-select></el-form-item><el-form-item label="协办部门（最多两个）"><el-select v-model="form.collaboratorDeptIds" multiple :multiple-limit="2" filterable><el-option v-for="d in collaborationDepartments" :key="d.id" :disabled="d.id===form.hostDeptId" :value="d.id" :label="`${d.companyName||d.companyId||''} / ${d.name}`"/></el-select></el-form-item><p v-if="collaborationDepartments.some(d=>form.collaboratorDeptIds.includes(d.id)&&d.companyId!==form.companyId)" class="notice">包含跨公司协作，相关部门确认前将仅接收必要的协办信息。</p><el-form-item v-if="suggestionChanged" label="调整分配建议的原因" required><el-input v-model="assignmentReason" type="textarea" :rows="2" maxlength="1000" placeholder="说明实际职责或本次协作安排"/></el-form-item><div class="form-footer"><span class="muted">{{ draftState||'每30秒保存本次会话草稿' }}</span><el-button :disabled="busy" @click="saveDraft">保存草稿</el-button><el-button type="primary" native-type="submit" :loading="busy">创建任务</el-button></div></el-form></section><aside class="panel match-panel"><p class="eyebrow">FUNCTION MATCH</p><h2>职能匹配建议</h2><p class="muted">标题与内容变更后自动更新建议。建议只供参考，您可以手动调整。</p><div v-if="matching" role="status" class="loading">正在匹配职能…</div><el-alert v-else-if="matchError" :title="matchError+'；您仍可手动分配'" type="warning" :closable="false"/><div v-else-if="!match?.suggestions?.length" class="match-empty">填写任务信息后，这里将展示<br>命中职能、理由与规则版本。</div><div v-for="s in match?.suggestions||[]" :key="s.deptId" class="match-card"><div class="row-between"><b>{{ s.deptName }}</b><span class="score">{{ s.score }} 分</span></div><p>{{ ['HOST','MASTER'].includes(s.role)?'建议主办':'建议协办' }}</p><ul><li v-for="(r,i) in s.reasons" :key="i">{{ typeof r==='string'?r:JSON.stringify(r) }}</li></ul><el-button size="small" plain @click="applySuggestion(s)">采用建议</el-button></div><p v-if="match" class="scope-note">规则版本 {{ match.ruleVersion }} · 命中词、否定词与人工兜底以规则解释为准。</p><el-button text @click="fetchMatch">重新匹配</el-button></aside></div></template>
